Caching:
export async function loader({ request }) {
  const data = await getData();
  const etag = hash(data);
  if (request.headers.get('If-None-Match') === etag) {
    return new Response(null, { status: 304 });
  }
  return json(data, { headers: { ETag: etag } });
}
